  xs: 'size-3',
  sm: 'size-4',
  md: 'size-5',
  lg: 'size-6',
  xl: 'size-8',
};

/** Tamaño intrínseco del SVG (visible aunque no haya Tailwind cargado). */
const ICON_SIZE_PX: Record<WiIconSize, number> = {
  xs: 12,
  sm: 16,
  md: 20,
  lg: 24,
  xl: 32,
