 * - Sin `label`: decorativo (`aria-hidden="true"`).
 * - Con `label`: `role="img"` + `aria-label`.
 */
@Component({
  selector: 'wi-icon',
  host: {
    class: 'wi-icon inline-block shrink-0 text-current leading-none',
  },
